local CommonTabToggleUpCell = Class("CommonTabToggleUpCell")
function CommonTabToggleUpCell:__init()
    self.isLock = nil
    self.lockImage = nil
end

function CommonTabToggleUpCell:__delete()
    self.data = nil
    self.isLock = nil
    self.lockImage = nil
    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function CommonTabToggleUpCell:SetCallBack(cb)
    self.__callback = cb
end

function CommonTabToggleUpCell:Awake()
    if self.LockGroup then
        self.lockImage = self.LockGroup.transform:Find("ImgLock")
    end
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function()
        if type(self.__callback) == 'function' then
            self.__callback()
        end
    end
    self.shadowComp = self.TxtTabName.gameObject:GetComponent(typeof(Shadow))
end

function CommonTabToggleUpCell:FreshName(text)
    CfUtils.FillText(self.TxtTabName, text)
end

function CommonTabToggleUpCell:FreshBaseUI(data)
    self.data = data
    self:FreshName(data.text)
    CfUtils.FillText(self.LockTxtTabName, data.text)
    
    self.hasIcon = not isNull(data.selectImgPath)
    self.showNormalBg = data.showNormalBg or false
    self.showBlackBg = data.showBlackBg or false
    if data.selectImgPath then
        CfUtils.FillImage(self.ImgIcon, data.selectImgPath)
        KTool.SetActive(self.ImgIcon, true)
    else
        KTool.SetActive(self.ImgIcon, false)
    end

    if not isNull(self.UIFX_UnLock) then
        if self.data.isNeedPlay and not isNull(self.data.aniName) then
            CfUtils.PlayAnimation(self.controller.gameObject,self.data.aniName)
        end
    end
    
    CfUtils.SetActive(self.ImgNew, checkBool(data.isNew))
    self:RefreshCountDown()

    --if not isNull(data.textColor) then
    --    self.textColor = data.textColor
    --end
    --if not isNull(data.fontSize) then
    --    self.fontSize = data.fontSize
    --end
end

function CommonTabToggleUpCell:FreshSelectStatus(isSelected)
    KTool.SetActive(self.ImgSelect, isSelected)
    KTool.SetActive(self.ImgArrow, self.hasIcon and isSelected)
    KTool.SetActive(self.ImgNormalBg2, (self.hasIcon or self.showNormalBg) and (not isSelected))
    if isNotNull(self.ImgNormalBg3) then
        KTool.SetActive(self.ImgNormalBg3, self.showBlackBg and (not isSelected))
    end
    CfUtils.SetUISwitchImage(self.ImgIcon, isSelected and SwitchTextStatusEnum.Selected or SwitchTextStatusEnum.Default)
    --if not isNull(self.textColor) then
    --    CfUtils.SetColor(self.TxtTabName, isSelected and self.textColor.selected or self.textColor.default)
    --end
    --if not isNull(self.fontSize) then
    --    CfUtils.SetTextFontSize(self.TxtTabName, isSelected and self.fontSize.selected or self.fontSize.default)
    --end
    local tabNameStatus
    if isSelected then
        tabNameStatus = SwitchTextStatusTabName.Selected
    else
        tabNameStatus = (self.hasIcon or self.showNormalBg) and SwitchTextStatusTabName.Unselected2 or  SwitchTextStatusTabName.Unselected1
    end
    CfUtils.SetUISwitchText(self.TxtTabName, tabNameStatus)
    CfUtils.SetUISwitchText(self.LockTxtTabName, tabNameStatus)
    if isNotNull(self.LockGroup) then
        local lockIcon = self.LockGroup:Find("ImgLock")
        if isNotNull(lockIcon) then
            CfUtils.SetUISwitchImage(lockIcon, tabNameStatus)
        end
    end
    if not isNull(self.shadowComp) then
        local shadowStatus
        if self.hasIcon or self.showNormalBg then
            shadowStatus = isSelected
        else
            shadowStatus = true
        end
        self.shadowComp.enabled = shadowStatus
    end
end

function CommonTabToggleUpCell:OnDestroy()
    self:RemoveTimer()
    self.data = nil
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

---设置锁定状态
---@param isLock boolean 是否锁定
function CommonTabToggleUpCell:SetLockState(isLock)
    self.isLock = isLock
    CfUtils.SetActive(self.LockGroup, isLock)
    CfUtils.SetActive(self.UnlockGroup, not isLock)
end

function CommonTabToggleUpCell:SetLockStatus(status)
    if status then
        CfUtils.SetUISwitchImage(self.lockImage, status)
        CfUtils.SetUISwitchText(self.LockTxtTabName, status)
    end
end

---@param isShowRedPoint boolean
function CommonTabToggleUpCell:FreshRedPointStatus(isShowRedPoint)
    CfUtils.SetActive(self.redPoint, isShowRedPoint == true)
end

function CommonTabToggleUpCell:RefreshCountDown()
    if not isNull(self.Countdown) then
        if self.data.countDownData  then
            if self.data.countDownData.isCountDown then
                if self.data.countDownData.remainTime > 0 then
                    KTool.SetActive(self.Countdown.gameObject,true)
                    self:StartTimer(self.data.countDownData.remainTime)
                else
                    KTool.SetActive(self.Countdown.gameObject,false)
                end
            elseif self.data.countDownData.isNormalTime then
                KTool.SetActive(self.Countdown.gameObject,true)
                CfUtils.FillText(self.CountdownTextTime,CfUtils.GetTimeHMS10(checkNumber(self.data.countDownData.remainTime)))
            else
                KTool.SetActive(self.Countdown.gameObject,false)
            end
        else
            KTool.SetActive(self.Countdown.gameObject,false)
        end
    end
end

function CommonTabToggleUpCell:StartTimer(remainTime)
    local textType = checkNumber(self.data.countDownData.textType)
    if textType == 2 then
        CfUtils.FillText(self.CountdownTextTime, localize("剩余_num_", { _num_ = CfUtils.GetTimeHMS10(checkNumber(remainTime)) }))
    else
        CfUtils.FillText(self.CountdownTextTime,CfUtils.GetTimeHMS10(checkNumber(remainTime)))
    end
    self:RemoveTimer()
    if remainTime > 0 then
        self.isTimeOver = false
        self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                if textType == 2 then
                    CfUtils.FillText(self.CountdownTextTime, localize("剩余_num_", { _num_ = CfUtils.GetTimeHMS10(checkNumber(count)) }))
                else
                    CfUtils.FillText(self.CountdownTextTime,CfUtils.GetTimeHMS10(checkNumber(count)))
                end
            else
                if textType == 2 then
                    CfUtils.FillText(self.CountdownTextTime, localize("已结束"))
                else
                    CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(0)))
                end
                CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
                self.isTimeOver = true
                self.Timer = nil
            end
        end, remainTime + 1, false, true)
    end
end

function CommonTabToggleUpCell:RemoveTimer()
    if self.Timer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
        self.Timer = nil
    end
end


return CommonTabToggleUpCell